    request = {**data, 'strategy': strategy, 'chunk_size': 120}
    result = chunk_documents(request)
    records = result['records']

    print(f'=== {strategy} strategy: {len(records)} records ===')

    # Verify all required fields present
    required = {'chunk_id', 'document_id', 'ordinal', 'text', 'char_start', 'char_end', 'units', 'metadata'}
    for r in records:
        missing = required - set(r.keys())
        extra = set(r.keys()) - required
        if missing:
            print(f'  MISSING FIELDS: {missing}')
        if extra:
            print(f'  EXTRA FIELDS: {extra}')

    # Verify per-document ordinals from 0 and contiguous
    doc_ordinals = {}
    for r in records:
        did = r['document_id']
        doc_ordinals.setdefault(did, []).append(r['ordinal'])
    for did, ords in doc_ordinals.items():
        expected = list(range(len(ords)))
        if ords != expected:
            print(f'  ORDINAL MISMATCH for {did}: {ords} != {expected}')
    print(f'  Documents: {list(doc_ordinals.keys())}')
    for did, ords in doc_ordinals.items():
        print(f'    {did}: ordinals {ords[0]}..{ords[-1]} ({len(ords)} chunks)')

    # Verify offsets slice back
    # Build a lookup: document_id -> original text
    doc_texts = {d['document_id']: d['text'] for d in data['documents']}
    for r in records:
        did = r['document_id']
        orig = doc_texts[did]
        sliced = orig[r['char_start']:r['char_end']]
        if sliced != r['text']:
            print(f'  SLICE MISMATCH for {r[\"chunk_id\"]}: {sliced!r} != {r[\"text\"]!r}')

    # Verify units == char_end - char_start
    for r in records:
        if r['units'] != r['char_end'] - r['char_start']:
            print(f'  UNITS MISMATCH for {r[\"chunk_id\"]}: {r[\"units\"]} != {r[\"char_end\"] - r[\"char_start\"]}')

    # Verify metadata passthrough
    doc_meta = {d['document_id']: d.get('metadata', {}) for d in data['documents']}
    for r in records:
        expected_meta = doc_meta[r['document_id']]
        if r['metadata'] != expected_meta:
            print(f'  METADATA MISMATCH for {r[\"chunk_id\"]}: {r[\"metadata\"]} != {expected_meta}')

    print('  All checks passed.')
    print()
